test:
bad_calls = [
    lambda: simulate_pending_death([], 1, 1),
    lambda: simulate_pending_death([[4]], 1, 1),
    lambda: simulate_pending_death([[1]], 0, 1),
    lambda: simulate_pending_death([[1]], 1, 0),
    lambda: simulate_pending_death([[1]], 1, 1, infection_threshold=0),
]
for call in bad_calls:
    try:
        call()
        assert False, 'expected ValueError'
    except ValueError:
        pass
